  router.get("/public/:creatorId", async (req, res, next) => { try { const id = z.string().uuid().parse(req.params.creatorId); const client = createSupabaseClient(env); const { data: creator, error } = await client.from("creator_profiles").select("id,display_name,bio,primary_language,avatar_url").eq("id", id).eq("status", "ACTIVE").maybeSingle(); if (error || !creator) return res.status(404).json({ error: { code: "CREATOR_NOT_FOUND", message: "Creator not found." } }); const { data: stories } = await client.from("catalog_content").select("id,title,description,content_type,language,estimated_duration_seconds,published_at").eq("creator_id", id).eq("status", "PUBLISHED").eq("visibility", "PUBLIC").order("published_at", { ascending: false }); const { count: followerCount } = await client.from("creator_follows").select("follower_user_id", { count: "exact", head: true }).eq("creator_id", id); res.json({ data: { creator: { ...creator, followerCount: followerCount ?? 0 }, stories: stories ?? [] } }); } catch (error) { next(error); } });
  router.get("/public/:creatorId/verification", async (req, res, next) => { try { const id = z.string().uuid().parse(req.params.creatorId); const client = createSupabaseClient(env); const { data: creator } = await client.from("creator_profiles").select("id").eq("id", id).eq("status", "ACTIVE").maybeSingle(); if (!creator) return res.status(404).json({ error: { code: "CREATOR_NOT_FOUND", message: "Creator not found." } }); const { data, error } = await client.from("creator_verifications").select("status").eq("creator_id", id).eq("status", "VERIFIED").maybeSingle(); if (error) throw error; res.json({ data: { status: data ? "VERIFIED" : "NOT_APPLIED" } }); } catch (error) { next(error); } });
