  router.post("/submissions/:submissionId/upload-url", async (req, res, next) => { try { if (!storage) throw new ApiError(503, "STORAGE_UNAVAILABLE", "Secure manuscript upload is unavailable."); const id = z.string().uuid().parse(req.params.submissionId); const input = uploadSchema.parse(req.body); if (input.sizeBytes > env.MAX_UPLOAD_SIZE_MB * 1024 * 1024) throw new ApiError(413, "FILE_TOO_LARGE", "This manuscript is too large."); const { data: submission } = await req.supabase!.from("creator_submissions").select("id,creator_id,status").eq("id", id).maybeSingle(); const { data: creator } = await req.supabase!.from("creator_profiles").select("id").eq("user_id", req.auth!.id).maybeSingle(); if (!submission || !creator || submission.creator_id !== creator.id) throw new ApiError(404, "SUBMISSION_NOT_FOUND", "Submission not found."); if (!( ["DRAFT", "CHANGES_REQUESTED"] as string[]).includes(submission.status)) throw new ApiError(409, "SUBMISSION_NOT_EDITABLE", "This submission cannot accept a manuscript now."); const key = `quarantine/creators/${creator.id}/submissions/${id}/uploads/original`; const upload = await storage.createUploadUrl({ key, contentType: input.mimeType, contentLength: input.sizeBytes, expiresInSeconds: env.S3_PRESIGNED_URL_EXPIRES_SECONDS }); const { error: recordError } = await req.supabase!.from("document_uploads").insert({ user_id: req.auth!.id, creator_submission_id: id, upload_context: "CREATOR_SUBMISSION", original_filename: input.originalFilename, declared_mime_type: input.mimeType, storage_key: key }); if (recordError) throw new ApiError(500, "UPLOAD_RECORD_CREATE_FAILED", "Unable to prepare the manuscript upload."); res.json({ data: { uploadUrl: upload.url, requiredHeaders: upload.headers, expiresAt: upload.expiresAt, key, filename: input.originalFilename, sizeBytes: input.sizeBytes } }); } catch (error) { next(error); } });
  router.post("/submissions/:submissionId/upload-complete", async (req, res, next) => { try { if (!storage) throw new ApiError(503, "STORAGE_UNAVAILABLE", "Secure manuscript upload is unavailable."); const id = z.string().uuid().parse(req.params.submissionId); const { data: record } = await req.supabase!.from("document_uploads").select("id,user_id,storage_key,declared_mime_type,original_filename").eq("creator_submission_id", id).eq("user_id", req.auth!.id).order("created_at", { ascending: false }).limit(1).maybeSingle(); if (!record) throw new ApiError(404, "UPLOAD_RECORD_NOT_FOUND", "Upload not found."); const metadata = await storage.getObjectMetadata({ key: record.storage_key }); if (!metadata?.contentLength || metadata.contentLength > env.MAX_UPLOAD_SIZE_MB * 1024 * 1024) throw new ApiError(400, "UPLOAD_VERIFICATION_FAILED", "The uploaded document could not be verified."); const tempPath = path.join(os.tmpdir(), `playbook-creator-upload-${record.id}`); const admin = env.SUPABASE_SERVICE_ROLE_KEY ? createSupabaseAdminClient(env) : req.supabase!; try { await storage.downloadObject({ key: record.storage_key, destination: tempPath }); const bytes = new Uint8Array(await readFile(tempPath)); const hash = createHash("sha256").update(bytes).digest("hex"); const validation = await validateDocumentBytes(bytes, record.declared_mime_type, env.MAX_IMAGE_PIXELS); if (!validation.valid) { const reference = await recordSecurityEvent(admin, { uploadId: record.id, userId: req.auth!.id, eventType: validation.reasonCode ?? "INVALID_DOCUMENT", severity: "LOW", reasonCode: validation.reasonCode ?? "INVALID_DOCUMENT", safeSummary: validation.summary ?? "The document could not be accepted.", detectedFileType: validation.detectedMimeType, fileSha256: hash }); await req.supabase!.from("document_uploads").update({ security_status: "REJECTED", validation_status: "INVALID", sha256: hash, incident_reference: reference }).eq("id", record.id); throw new ApiError(400, "INVALID_DOCUMENT", `${validation.summary ?? "The document could not be accepted."} Reference ${reference}.`); } const scan = scanner ? await scanner.scan({ bucket: env.QUARANTINE_BUCKET ?? env.AWS_S3_BUCKET, storageKey: record.storage_key, uploadId: record.id, sha256: hash }) : { status: "SCAN_FAILED" as const, provider: "none", code: "SCANNER_NOT_CONFIGURED" }; if (scan.status !== "CLEAN") throw new ApiError(400, "SECURITY_REJECTED", "This file could not be accepted for security reasons."); await req.supabase!.from("document_uploads").update({ security_status: "CLEAN", validation_status: "VALID", detected_mime_type: validation.detectedMimeType, file_size_bytes: metadata.contentLength, sha256: hash }).eq("id", record.id); const { data, error } = await req.supabase!.from("creator_submissions").update({ source_storage_key: record.storage_key, source_original_filename: record.original_filename, source_mime_type: record.declared_mime_type, source_size_bytes: metadata.contentLength, source_sha256: null, processing_error_code: null }).eq("id", id).eq("creator_id", (await req.supabase!.from("creator_profiles").select("id").eq("user_id", req.auth!.id).single()).data?.id).select("id,status,source_original_filename,source_size_bytes").single(); if (error || !data) throw new ApiError(500, "UPLOAD_COMPLETE_FAILED", "Unable to save the verified manuscript."); res.json({ data }); } finally { await rm(tempPath, { force: true }); } } catch (error) { next(error); } });
